'use client';

import React, { useEffect, useRef } from 'react';
import styles from './CursorGlow.module.css';

interface Bean {
    x: number;
    y: number;
    size: number;
    rotation: number;
    rotationSpeed: number;
    opacity: number;
    velocityX: number;
    velocityY: number;
    life: number;
}

export default function CursorGlow() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const beansRef = useRef<Bean[]>([]);
    const mouseRef = useRef({ x: -100, y: -100 });
    const lastSpawnRef = useRef(0);
    const animationRef = useRef<number>(0);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const resize = () => {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        };
        resize();
        window.addEventListener('resize', resize);

        const handleMove = (e: MouseEvent) => {
            mouseRef.current = { x: e.clientX, y: e.clientY };
        };

        window.addEventListener('mousemove', handleMove);

        const spawnBean = () => {
            const { x, y } = mouseRef.current;
            if (x < 0) return;

            beansRef.current.push({
                x,
                y,
                size: Math.random() * 10 + 8,
                rotation: Math.random() * Math.PI * 2,
                rotationSpeed: (Math.random() - 0.5) * 0.08,
                opacity: 1,
                velocityX: (Math.random() - 0.5) * 2,
                velocityY: Math.random() * 1 + 0.5,
                life: 1,
            });
        };

        const drawBean = (ctx: CanvasRenderingContext2D, bean: Bean) => {
            ctx.save();
            ctx.translate(bean.x, bean.y);
            ctx.rotate(bean.rotation);
            ctx.globalAlpha = bean.opacity * bean.life;

            // 커피빈 모양 그리기
            const s = bean.size;
            ctx.fillStyle = '#6f4a31';
            ctx.beginPath();
            ctx.ellipse(0, 0, s, s * 0.65, 0, 0, Math.PI * 2);
            ctx.fill();

            // 가운데 선 (커피빈 특유의 줄)
            ctx.strokeStyle = '#503520';
            ctx.lineWidth = 1.2;
            ctx.globalAlpha = bean.opacity * bean.life * 0.7;
            ctx.beginPath();
            ctx.moveTo(0, -s * 0.5);
            ctx.bezierCurveTo(s * 0.15, -s * 0.15, -s * 0.15, s * 0.15, 0, s * 0.5);
            ctx.stroke();

            ctx.restore();
        };

        const animate = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            const now = Date.now();
            // 60ms마다 하나씩 생성 (마우스 움직일 때만)
            if (now - lastSpawnRef.current > 60) {
                spawnBean();
                lastSpawnRef.current = now;
            }

            beansRef.current.forEach((bean) => {
                bean.x += bean.velocityX;
                bean.y += bean.velocityY;
                bean.rotation += bean.rotationSpeed;
                bean.life -= 0.012;
                bean.opacity = Math.max(0, bean.life);
            });

            // 죽은 파티클 제거
            beansRef.current = beansRef.current.filter((b) => b.life > 0);

            // 그리기
            beansRef.current.forEach((bean) => drawBean(ctx, bean));

            animationRef.current = requestAnimationFrame(animate);
        };

        animate();

        return () => {
            window.removeEventListener('resize', resize);
            window.removeEventListener('mousemove', handleMove);
            cancelAnimationFrame(animationRef.current);
        };
    }, []);

    return <canvas ref={canvasRef} className={styles.glow} />;
}
