'use client';

import React, { useEffect, useRef } from 'react';
import styles from './CoffeeSteam.module.css';

interface SteamParticle {
    x: number;
    y: number;
    originX: number;
    size: number;
    opacity: number;
    life: number;
    speed: number;
    wobbleOffset: number;
    wobbleSpeed: number;
    wobbleAmp: number;
}

export default function CoffeeSteam() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const particlesRef = useRef<SteamParticle[]>([]);
    const animationRef = useRef<number>(0);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const resize = () => {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        };
        resize();
        window.addEventListener('resize', resize);

        // 스팀 발생 위치 (화면 하단 3곳)
        const getSpawnPoints = () => {
            const w = canvas.width;
            return [
                w * 0.2,
                w * 0.5,
                w * 0.8,
            ];
        };

        const spawnSteam = () => {
            const points = getSpawnPoints();
            const originX = points[Math.floor(Math.random() * points.length)];
            const spread = 40;

            particlesRef.current.push({
                x: originX + (Math.random() - 0.5) * spread,
                y: canvas.height + 20,
                originX,
                size: Math.random() * 30 + 15,
                opacity: Math.random() * 0.15 + 0.08,
                life: 1,
                speed: Math.random() * 1.2 + 0.6,
                wobbleOffset: Math.random() * Math.PI * 2,
                wobbleSpeed: Math.random() * 0.02 + 0.01,
                wobbleAmp: Math.random() * 40 + 20,
            });
        };

        let frameCount = 0;

        const animate = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            frameCount++;

            // 3프레임마다 하나씩 생성
            if (frameCount % 3 === 0) {
                spawnSteam();
            }

            particlesRef.current.forEach((p) => {
                // 위로 올라감
                p.y -= p.speed;

                // 좌우 구불구불 움직임
                p.wobbleOffset += p.wobbleSpeed;
                p.x = p.originX + Math.sin(p.wobbleOffset) * p.wobbleAmp;

                // 올라가면서 커지고 투명해짐
                p.size += 0.3;
                p.life -= 0.003;
                p.opacity = Math.max(0, p.life * 0.2);

                // 그리기
                const gradient = ctx.createRadialGradient(
                    p.x, p.y, 0,
                    p.x, p.y, p.size
                );
                gradient.addColorStop(0, `rgba(255, 255, 255, ${p.opacity})`);
                gradient.addColorStop(0.4, `rgba(245, 240, 235, ${p.opacity * 0.6})`);
                gradient.addColorStop(1, `rgba(235, 225, 215, 0)`);

                ctx.beginPath();
                ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                ctx.fillStyle = gradient;
                ctx.fill();
            });

            // 죽은 파티클 제거
            particlesRef.current = particlesRef.current.filter((p) => p.life > 0);

            animationRef.current = requestAnimationFrame(animate);
        };

        animate();

        return () => {
            window.removeEventListener('resize', resize);
            cancelAnimationFrame(animationRef.current);
        };
    }, []);

    return <canvas ref={canvasRef} className={styles.canvas} />;
}
